#!/bin/sh
# Standalone installer. Python 3.8+ required. Git only for submodule mode.
set -eu
python_cmd=
for candidate in python3 python; do
    if command -v "$candidate" >/dev/null 2>&1 && "$candidate" -c 'import sys;sys.exit(0 if sys.version_info >= (3,8) else 1)' 2>/dev/null; then
        python_cmd=$candidate
        break
    fi
done
if [ -z "$python_cmd" ]; then
    echo 'ERROR: Python 3.8+ is required on PATH.' >&2
    exit 1
fi
exec "$python_cmd" -c 'import base64,zlib;exec(compile(zlib.decompress(base64.b64decode('"'"''"'"')),'"'"'stm32-rtt-installer'"'"','"'"'exec'"'"'))' "$@"
